$config=require dirname(__DIR__).'/bootstrap.php';$pdo=\EasyIT\LicenseServer\Database\Connection::create($config['database']);(new \EasyIT\LicenseServer\Database\MigrationRunner($pdo))->migrate();$now=time();$customer='CUS-'.bin2hex(random_bytes(8));$license='LICID-'.bin2hex(random_bytes(8));$number='LIC-'.date('Y').'-'.strtoupper(bin2hex(random_bytes(4)));$secret=rtrim(strtr(base64_encode(random_bytes(24)),'+/','-_'),'=');$key=$number.'.'.$secret;$pdo->prepare('INSERT INTO customers (customer_id,customer_number,name,company,email,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)')->execute([$customer,'DEV-'.strtoupper(bin2hex(random_bytes(3))),'Development','easyIT DEV',null,'active',$now,$now]);$pdo->prepare('INSERT INTO licenses (license_id,license_number,activation_secret_hash,customer_id,status,valid_from,valid_until,max_installations,lease_seconds,grace_seconds,generation,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$license,$number,password_hash($secret,PASSWORD_DEFAULT),$customer,'active',$now-60,$now+31536000,5,3600,86400,1,$now,$now]);$lm=$pdo->prepare('INSERT INTO license_modules (license_id,module_code,enabled,valid_from,valid_until,configuration) VALUES (?,?,?,?,?,?)');foreach(['dataform','designer','export','api','themes'] as $m)$lm->execute([$license,$m,1,null,null,null]);$pdo->prepare('INSERT INTO license_policies (license_id,max_dataforms,created_at,updated_at) VALUES (?,?,?,?)')->execute([$license,5,$now,$now]);$caps=$pdo->query('SELECT capability_code FROM capability_registry WHERE active=1')->fetchAll();$lc=$pdo->prepare('INSERT INTO license_capabilities (license_id,capability_code,enabled,created_at,updated_at) VALUES (?,?,?,?,?)');foreach($caps as $c)$lc->execute([$license,(string)$c['capability_code'],1,$now,$now]);$def=['view'=>['mode'=>'form','page_size'=>20,'fulltext_search'=>true,'filter'=>true,'addClass'=>'','addJavaScript'=>''],'capabilities'=>['dataset.read','dataset.create','dataset.update','dataset.delete','relation.read','relation.createChild'],'fields'=>[['name'=>'id','type'=>'integer','readonly'=>true],['name'=>'name','type'=>'text','readonly'=>false],['name'=>'email','type'=>'text','readonly'=>false]],'events'=>['dataform'=>['open','close'],'dataset'=>['before_save','after_save','before_insert','after_insert','before_update','after_update','before_delete','after_delete']],'relations'=>[]];$json=json_encode($def,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$pdo->prepare('INSERT INTO dataform_definitions (definition_id,project_id,dataform_id,revision_number,status,definition_json,definition_hash,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?)')->execute(['DEF-'.bin2hex(random_bytes(8)),'1','1',1,'published',$json,hash('sha256',$json),$now,$now]);echo "DEV LICENSE CREATED\nlicense_key=".$key."\nproject_id=1\ndataform_id=1\n";
